(function(E){ const x = E["exam-03"] = E["exam-03"] || {units:{}}; (x.units = x.units || {})["x03-r3"] = {"id":"x03-r3","patterns":["RA-history","GT3-history","PARA-cause","PARA-research"],"title":{"en":"Reading 3: Passage 3 / Section 3","tr":"Reading 3: Passage 3 / Section 3","fa":"Reading ۳: متن ۳ (Passage 3) / بخش ۳ (Section 3)"},"objective":{"en":"In this lesson you will learn to follow a writer who challenges an old idea: answer multiple-choice questions, match sentence beginnings to their endings, and decide YES, NO or NOT GIVEN about the writer’s own views.","tr":"Bu derste eski bir fikre karşı çıkan bir yazarı takip etmeyi öğreneceksin: çoktan seçmeli soruları cevaplayacak, cümle başlarını sonlarıyla eşleştirecek ve yazarın kendi görüşleri için YES, NO ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری نویسنده‌ای را دنبال کنی که یک ایده‌ی قدیمی را زیر سؤال می‌برد: به سؤال‌های چندگزینه‌ای جواب بدهی، ابتدای جمله‌ها را به پایانشان وصل کنی و درباره‌ی نظرهای خودِ نویسنده بین YES، NO و NOT GIVEN تصمیم بگیری."},"objectiveGT":{"en":"In this lesson you will learn to choose a heading for each section of a long history article, answer multiple-choice questions about causes and decisions, and complete a summary with single words from the text.","tr":"Bu derste uzun bir tarih makalesinin her bölümü için bir başlık seçmeyi, nedenler ve kararlarla ilgili çoktan seçmeli soruları cevaplamayı ve bir özeti metindeki tek kelimelerle tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری برای هر بخش یک مقاله‌ی تاریخی بلند عنوان انتخاب کنی، به سؤال‌های چندگزینه‌ای درباره‌ی علت‌ها و تصمیم‌ها جواب بدهی و یک خلاصه را با تک‌کلمه‌هایی از متن کامل کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 3: an argument about the past","tr":"Reading Passage 3: geçmiş üzerine bir tartışma yazısı","fa":"Reading Passage 3: استدلالی درباره‌ی گذشته"},"objective":{"en":"In this lesson you will learn to follow a writer who challenges an old idea: answer multiple-choice questions, match sentence beginnings to their endings, and decide YES, NO or NOT GIVEN about the writer’s own views.","tr":"Bu derste eski bir fikre karşı çıkan bir yazarı takip etmeyi öğreneceksin: çoktan seçmeli soruları cevaplayacak, cümle başlarını sonlarıyla eşleştirecek ve yazarın kendi görüşleri için YES, NO ya da NOT GIVEN’a karar vereceksin.","fa":"در این درس یاد می‌گیری نویسنده‌ای را دنبال کنی که یک ایده‌ی قدیمی را زیر سؤال می‌برد: به سؤال‌های چندگزینه‌ای جواب بدهی، ابتدای جمله‌ها را به پایانشان وصل کنی و درباره‌ی نظرهای خودِ نویسنده بین YES، NO و NOT GIVEN تصمیم بگیری."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"14"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Endings","tr":"Sonlar","fa":"پایان‌ها"},"value":"A-F"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: how farming really began","tr":"Bu sınav: tarım gerçekte nasıl başladı","fa":"این آزمون: کشاورزی واقعاً چطور شروع شد"},"intro":{"en":"History is one of the most common subjects for Passage 3, often as an argument: an old explanation, new evidence, and the writer’s position. The questions test whether you can separate the evidence from the writer’s opinion.","tr":"Tarih, Passage 3’ün en yaygın konularından biridir; çoğu zaman bir tartışma biçiminde: eski bir açıklama, yeni kanıtlar ve yazarın tutumu. Sorular kanıtları yazarın görüşünden ayırıp ayıramadığını ölçer.","fa":"تاریخ یکی از رایج‌ترین موضوع‌های Passage 3 است، اغلب به شکل استدلال: یک توضیح قدیمی، شواهد تازه و موضع نویسنده. سؤال‌ها می‌سنجند آیا می‌توانی شواهد را از نظر نویسنده جدا کنی."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x03-r3-ctx","exam":true,"patterns":["RA-history","PARA-research","PARA-cause"],"often":{"pattern":"RA-history","n":35,"of":120,"label":{"en":"Comes up often in the real exam: 35 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 35’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۵ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"A new story of early farming","tr":"Erken tarımın yeni hikâyesi","fa":"داستان تازه‌ی کشاورزی آغازین"},"asks":{"en":"An argument about prehistory: the writer explains the old story of how farming began, shows the evidence against each part of it, and gives a view on whether farming was a mistake.","tr":"Tarih öncesi üzerine bir tartışma yazısı: yazar tarımın nasıl başladığına dair eski hikâyeyi anlatıyor, her bölümüne karşı kanıtları gösteriyor ve tarımın bir hata olup olmadığı konusunda bir görüş bildiriyor.","fa":"استدلالی درباره‌ی پیش از تاریخ: نویسنده داستان قدیمیِ آغاز کشاورزی را توضیح می‌دهد، شواهدِ علیه هر بخشش را نشان می‌دهد و درباره‌ی اینکه کشاورزی اشتباه بود یا نه نظر می‌دهد."},"fields":["The old story","A sudden change?","One place or many?","Building before farming","Health","A mistake?","Textbooks"],"words":[{"a":"precariously","b":"in an unsafe, uncertain way","tr":"güvencesiz bir biçimde","fa":"به شکلی ناامن و متزلزل"},{"a":"surplus","b":"more than is needed","tr":"fazlalık","fa":"مازاد"},{"a":"deliberate","b":"planned, done on purpose","tr":"kasıtlı, planlı","fa":"عمدی، برنامه‌ریزی‌شده"},{"a":"domesticated","b":"changed by people for farming","tr":"evcilleştirilmiş","fa":"اهلی‌شده"},{"a":"independently","b":"separately, without contact","tr":"birbirinden bağımsız","fa":"مستقل از هم"},{"a":"foraging","b":"collecting wild food","tr":"yabani yiyecek toplamak","fa":"جمع‌آوری غذای وحشی"},{"a":"monument","b":"a large structure built to be remembered","tr":"anıt","fa":"بنای یادبود"},{"a":"reverse the order","b":"turn it the other way round","tr":"sırayı tersine çevirmek","fa":"برعکس کردن ترتیب"},{"a":"varied","b":"with many different kinds","tr":"çeşitli","fa":"متنوع"},{"a":"outnumber","b":"be more in number than","tr":"sayıca geçmek","fa":"از نظر تعداد بیشتر بودن"},{"a":"foresee","b":"know in advance","tr":"önceden görmek","fa":"پیش‌بینی کردن"},{"a":"I cannot agree with","b":"I disagree with","tr":"... katılamam","fa":"نمی‌توانم با ... موافق باشم"}],"traps":[{"en":"The writer quotes other people (\"one popular writer described...\") before giving a different view. A YES / NO statement must match the writer’s own view.","tr":"Yazar farklı bir görüş vermeden önce başkalarını alıntılar (\"popüler bir yazar ... diye tanımladı\"). YES / NO ifadesi yazarın kendi görüşüne uymalıdır.","fa":"نویسنده قبل از نظر متفاوت خودش حرف دیگران را نقل می‌کند («یک نویسنده‌ی پرطرفدار ... توصیف کرد»). جمله‌ی YES / NO باید با نظر خودِ نویسنده جور باشد."},{"en":"In sentence endings, several endings are grammatically possible. Choose by meaning, checking the paragraph each sentence comes from.","tr":"Cümle sonlarında birden fazla son dilbilgisi açısından mümkündür. Her cümlenin geldiği paragrafı kontrol ederek anlama göre seç.","fa":"در کامل کردن جمله‌ها، چند پایان از نظر دستوری ممکن‌اند. با توجه به معنی و با چک کردن پاراگرافی که هر جمله از آن آمده انتخاب کن."}],"example":{"text":"\"Some historians call the printing press the most important invention ever. I would not go so far, but its effect on education was enormous.\"","item":"Statement: The printing press was the most important invention in history. YES, NO or NOT GIVEN?","answer":"NO","why":{"en":"That is the historians’ view; the writer \"would not go so far\".","tr":"Bu tarihçilerin görüşü; yazar \"o kadar ileri gitmez\".","fa":"این نظر تاریخ‌دان‌هاست؛ نویسنده «تا این حد جلو نمی‌رود»."}}},{"id":"RA-culture","ctx":["RA-history","RA-culture"],"title":{"en":"Arguments about art, heritage and history","tr":"Sanat, miras ve tarih üzerine tartışma yazıları","fa":"نوشته‌های استدلالی درباره‌ی هنر، میراث و تاریخ"},"asks":{"en":"A review or an argument about art, museums, heritage or history: should museums return objects, is street art real art, what a history book gets right. YES/NO/NOT GIVEN asks about the writer’s views; multiple choice asks about the writer’s purpose.","tr":"Sanat, müzeler, kültürel miras ya da tarih üzerine bir eleştiri veya tartışma yazısı: müzeler eserleri iade etmeli mi, sokak sanatı gerçek sanat mı, bir tarih kitabı neyi doğru yapıyor. YES/NO/NOT GIVEN yazarın görüşlerini sorar; çoktan seçmeli sorular yazarın amacını sorar.","fa":"نقد یا نوشته‌ای استدلالی درباره‌ی هنر، موزه‌ها، میراث یا تاریخ: آیا موزه‌ها باید اشیا را پس بدهند، آیا هنر خیابانی هنر واقعی است، یک کتاب تاریخ چه چیزی را درست می‌گوید. YES/NO/NOT GIVEN نظر نویسنده را می‌پرسد؛ چندگزینه‌ای هدف نویسنده را."},"fields":["The writer believes the book is too long. (YES / NO / NOT GIVEN)","The writer’s main point in paragraph 3 is...","Museums should charge for entry. (YES / NO / NOT GIVEN)","Summary with a box: the writer thinks the ___ of the exhibition was..."],"words":[{"a":"the writer believes","b":"in my view / I would argue","tr":"yazara göre","fa":"نویسنده معتقد است"},{"a":"convincing","b":"persuasive / makes a strong case","tr":"ikna edici","fa":"قانع‌کننده"},{"a":"overrated","b":"praised more than it deserves","tr":"abartılmış","fa":"بیش از اندازه ستوده‌شده"},{"a":"neglected","b":"ignored / overlooked","tr":"ihmal edilmiş","fa":"نادیده‌گرفته‌شده"},{"a":"authentic","b":"genuine / the real thing","tr":"özgün","fa":"اصیل"},{"a":"controversial","b":"causes disagreement","tr":"tartışmalı","fa":"بحث‌برانگیز"},{"a":"heritage","b":"the past a community keeps","tr":"kültürel miras","fa":"میراث"},{"a":"accessible","b":"easy for the public to reach or understand","tr":"erişilebilir","fa":"در دسترس"},{"a":"criticise","b":"find fault with","tr":"eleştirmek","fa":"انتقاد کردن"},{"a":"underestimate","b":"think it matters less than it does","tr":"küçümsemek","fa":"دست‌کم گرفتن"},{"a":"admittedly","b":"it is true that... but","tr":"kabul etmek gerekir ki","fa":"البته"},{"a":"dismiss","b":"reject without serious thought","tr":"önemsememek","fa":"رد کردن"}],"traps":[{"en":"Reported views: \"some critics say the exhibition is too small\" is not the writer’s view unless the writer agrees.","tr":"Aktarılan görüşler: \"bazı eleştirmenler serginin küçük olduğunu söylüyor\" yazar katılmadıkça yazarın görüşü değildir.","fa":"نظرهای نقل‌شده: «بعضی منتقدها می‌گویند نمایشگاه کوچک است» نظر نویسنده نیست، مگر اینکه نویسنده موافق باشد."},{"en":"NOT GIVEN: the writer discusses the topic but gives no opinion on the exact point of the statement.","tr":"NOT GIVEN: yazar konuyu tartışır ama ifadedeki noktaya dair görüş bildirmez.","fa":"NOT GIVEN: نویسنده درباره‌ی موضوع حرف می‌زند، ولی درباره‌ی همان نکته‌ی جمله نظری نمی‌دهد."},{"en":"Concession: \"it is true that the museum is expensive, but...\". The writer’s real view comes after \"but\".","tr":"Kabul etme: \"müzenin pahalı olduğu doğru ama...\". Yazarın asıl görüşü \"but\"tan sonra gelir.","fa":"پذیرش موقت: «درست است که موزه گران است، اما...». نظر واقعی نویسنده بعد از «but» می‌آید."}],"example":{"text":"Critics have called the new gallery cold and unwelcoming. I disagree: its plain white rooms let the paintings speak for themselves, which is exactly what a gallery should do.","item":"Statement: The writer thinks the new gallery is unwelcoming.  (YES / NO / NOT GIVEN)","answer":"NO","why":{"en":"\"Unwelcoming\" is the critics’ view. \"I disagree\" makes the writer’s view the opposite: NO.","tr":"\"Soğuk\" eleştirmenlerin görüşü. \"Katılmıyorum\" yazarın görüşünü tersine çeviriyor: NO.","fa":"«بی‌روح» نظر منتقدهاست. «موافق نیستم» نظر نویسنده را برعکس می‌کند: NO."}},"track":"academic","general":true,"patterns":["RA-history"],"often":{"pattern":"RA-history","n":35,"of":120,"label":{"en":"Comes up often in the real exam: 35 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 35’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۳۵ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three tasks, one argument","tr":"Tek tartışma, üç görev","fa":"یک استدلال، سه تمرین"},"body":{"en":"Questions 27-30: multiple choice, A-D. Questions 31-34: complete each sentence with the correct ending from a list of six, A-F; two endings are not used. Questions 35-40: YES, NO or NOT GIVEN about the writer’s views.","tr":"Soru 27-30: çoktan seçmeli, A-D. Soru 31-34: her cümleyi altı sonluk listeden (A-F) doğru sonla tamamla; iki son kullanılmaz. Soru 35-40: yazarın görüşleri hakkında YES, NO ya da NOT GIVEN.","fa":"سؤال‌های ۲۷ تا ۳۰: چندگزینه‌ای، A تا D. سؤال‌های ۳۱ تا ۳۴: هر جمله را با پایان درست از فهرست شش‌تایی A تا F کامل کن؛ دو پایان استفاده نمی‌شوند. سؤال‌های ۳۵ تا ۴۰: YES، NO یا NOT GIVEN درباره‌ی نظرهای نویسنده."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Beginning first, then the ending","tr":"Önce baş, sonra son","fa":"اول ابتدا، بعد پایان"},"steps":[{"en":"For each sentence beginning, find the place in the passage before you look at the endings.","tr":"Her cümle başı için sonlara bakmadan önce metindeki yeri bul.","fa":"برای ابتدای هر جمله، قبل از نگاه کردن به پایان‌ها، جایش را در متن پیدا کن."},{"en":"Say the ending in your own words, then choose the option that means the same.","tr":"Sonu kendi kelimelerinle söyle, sonra aynı anlama gelen seçeneği seç.","fa":"پایان را با کلمه‌های خودت بگو و بعد گزینه‌ای را انتخاب کن که همان معنی را دارد."},{"en":"For YES / NO / NOT GIVEN, find the writer’s own words: I believe, I cannot agree, it would be wrong to.","tr":"YES / NO / NOT GIVEN için yazarın kendi sözlerini bul: I believe, I cannot agree, it would be wrong to.","fa":"برای YES / NO / NOT GIVEN حرف‌های خودِ نویسنده را پیدا کن: I believe، I cannot agree، it would be wrong to."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Possible is not the same as correct","tr":"Mümkün olan, doğru olanla aynı değil","fa":"ممکن با درست یکی نیست"},"body":{"en":"Several endings may make a grammatical sentence, and some repeat words from the passage. Only one says what the passage says about that beginning. Words such as \"only\", \"every\" and \"all\" often make an ending wrong.","tr":"Birkaç son dilbilgisi açısından doğru bir cümle kurabilir ve bazıları metindeki kelimeleri tekrar eder. Yalnızca biri metnin o başlangıç hakkında söylediğini söyler. \"Only\", \"every\" ve \"all\" gibi kelimeler çoğu zaman bir sonu yanlış yapar.","fa":"چند پایان ممکن است جمله‌ای دستوری بسازند و بعضی کلمه‌های متن را تکرار کنند. فقط یکی همان چیزی را می‌گوید که متن درباره‌ی آن ابتدا می‌گوید. کلمه‌هایی مثل «only»، «every» و «all» اغلب پایانی را غلط می‌کنند."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One sentence ending, step by step","tr":"Bir cümle sonu, adım adım","fa":"پایان یک جمله، قدم به قدم"},"instruction":"Complete the sentence with the correct ending, A-C.","text":"\"Writing was invented separately in Mesopotamia, Egypt, China and Central America, each time for different purposes.\"","item":"Writing developed... A only in the Middle East.  B in several places that had no contact.  C after paper was invented.","answer":"B","walk":[{"en":"Find the place: the sentence about where writing was invented.","tr":"Yeri bul: yazının nerede icat edildiğine dair cümle.","fa":"جایش را پیدا کن: جمله‌ای درباره‌ی جایی که نوشتن اختراع شد."},{"en":"In your own words: in different regions, separately.","tr":"Kendi kelimelerinle: farklı bölgelerde, birbirinden ayrı.","fa":"با کلمه‌های خودت: در منطقه‌های مختلف، جدا از هم."},{"en":"A is wrong (\"only\"), C is not in the text: choose B.","tr":"A yanlış (\"only\"), C metinde yok: B’yi seç.","fa":"A غلط است («only»)، C در متن نیست: B را انتخاب کن."}]},"quick":{"prompt":"Text: \"Some say the bridge was a waste of money. It would be wrong, however, to call it a failure.\" Statement: \"The bridge was a failure.\" YES, NO or NOT GIVEN?","options":["YES","NO","NOT GIVEN"],"correct":1,"why":{"en":"\"It would be wrong to call it a failure\" is the writer’s view, and it contradicts the statement.","tr":"\"Ona başarısızlık demek yanlış olur\" yazarın görüşü ve ifadeyle çelişiyor.","fa":"«اشتباه است که آن را شکست بنامیم» نظر نویسنده است و با جمله تناقض دارد."}},"remember":{"en":"Find the beginning in the passage first, choose the ending by meaning, and answer YES or NO only from the writer’s own words.","tr":"Önce başlangıcı metinde bul, sonu anlama göre seç ve YES ya da NO’yu yalnızca yazarın kendi sözlerine göre ver.","fa":"اول ابتدا را در متن پیدا کن، پایان را بر اساس معنی انتخاب کن و YES یا NO را فقط از روی حرف‌های خودِ نویسنده بده."},"type":"explain","id":"c-x03-r3-e","course":"ielts-exams","exam":"exam-03","unit":"x03-r3"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 3","title":{"en":"Rethinking the first farmers","tr":"İlk çiftçileri yeniden düşünmek","fa":"بازاندیشی درباره‌ی نخستین کشاورزان"},"timed":20,"ctx":["RA-history"],"intro":"You should spend about 20 minutes on Questions 27-40, which are based on Reading Passage 3 below.","passage":"Rethinking the first farmers\n\nFor most of the last century, the story of how humans began to farm was told as a tale of progress. Our ancestors, it was said, had lived precariously as hunters and gatherers until, around ten thousand years ago, someone discovered that seeds could be planted. Farming produced a surplus of food, the surplus allowed villages and then cities to grow, and civilisation followed. In the 1930s an Australian archaeologist gave this change a memorable name: the Neolithic Revolution. The phrase has lasted remarkably well. I believe it has also done a good deal of harm, because almost every part of the story it tells now looks doubtful.\n\nConsider first the word \"revolution\", which suggests a sudden and deliberate change. The evidence points the other way. People were collecting the seeds of wild cereals long before anyone farmed them; at one site in the Middle East, grains of wild barley and wheat have been found that are more than twenty thousand years old. Even after people began to plant crops, it took thousands of years for the plants to change into the domesticated forms we know. Wild wheat drops its seeds as soon as they are ripe, which is good for the plant but bad for anyone trying to harvest it. Domesticated wheat keeps its seeds on the stalk until someone cuts it. That change happened gradually, as farmers unknowingly favoured the plants that held on to their grain.\n\nNor did farming begin in one place and spread from there. Plants were domesticated independently in at least half a dozen regions, including the Middle East, China, New Guinea, Central America and the Andes. In each case the process was slow, and in some places groups seem to have moved back and forth between farming and foraging for many generations, depending on the climate and on what else was available. It seems likely that the warmer and more stable climate that followed the last ice age made this experimentation possible, although climate alone cannot explain why particular groups chose to farm.\n\nThe most striking challenge to the old story comes from a hilltop in what is now south-eastern Turkey. There, archaeologists have uncovered great circles of carved stone pillars, some over five metres tall, built more than eleven thousand years ago. Excavation began in the 1990s and continues today, and only a small part of the site has so far been uncovered. Their builders were hunter-gatherers; there is no sign of domesticated plants or animals at the site from that time. Large-scale building, in other words, came before farming in this region, not after it. Some researchers have even suggested that the need to feed the crowds who gathered to build such monuments may have encouraged people to cultivate cereals, reversing the traditional order of cause and effect.\n\nThe idea that farming made life better is also in trouble. When archaeologists compare skeletons from before and after the arrival of agriculture, they often find that early farmers were shorter, had worse teeth and suffered more from disease than the hunter-gatherers who came before them. Living close together, near their animals and their waste, allowed infections to spread, and a diet based on one or two crops was less varied than one based on wild foods. The repeated physical work of grinding grain and digging fields also left its mark on their bones. This pattern is found in many regions, though not in all. It would be wrong, however, to conclude that people were simply foolish to adopt farming. Whatever its costs for individuals, it allowed far more people to live on the same area of land, and farming populations grew until they outnumbered and replaced their neighbours.\n\nFor that reason I cannot agree with the popular writer who described agriculture as the worst mistake in the history of the human race. A mistake implies a choice made with knowledge of the result, and nobody in the past could have foreseen where the slow drift into farming would lead. What the new evidence shows is not that our ancestors chose badly, but that they did not really choose at all, at least not in the way the old story suggests.\n\nNone of this has yet reached most school textbooks, which still tell children about a single revolution in a single place. That is a pity, because the real story is more complicated, and far more interesting. It is a story of many peoples, in many places, finding their own ways through a changing world, with consequences that none of them could see.","groups":[{"instruction":"Questions 27-30. Choose the correct letter, A, B, C or D. Write the correct letter in boxes 27-30 on your answer sheet.","qtype":"mcq","questions":[{"n":27,"kind":"mcq","prompt":"What does the writer say about the term \"Neolithic Revolution\"?","options":["A It is no longer used.","B It describes the change accurately.","C It suggests a sudden change that did not happen.","D It was first used by scientists in the Middle East."],"correct":2,"evidence":"which suggests a sudden and deliberate change","why":{"en":"\"Revolution\" suggests \"a sudden and deliberate change\", and \"the evidence points the other way\". The phrase \"has lasted remarkably well\", so A is wrong.","tr":"\"Devrim\" kelimesi \"ani ve kasıtlı bir değişimi\" çağrıştırıyor ve \"kanıtlar ters yönü gösteriyor\". İfade \"şaşırtıcı biçimde varlığını sürdürdü\", yani A yanlış.","fa":"«انقلاب» «تغییری ناگهانی و عمدی» را القا می‌کند و «شواهد خلاف آن را نشان می‌دهند». این عبارت «به‌طرز عجیبی دوام آورده»، پس A غلط است."},"trap":["TR-paraphrase","TR-samewords"]},{"n":28,"kind":"mcq","prompt":"The writer mentions very old grains of wild barley and wheat in order to show that","options":["A people used cereals long before they farmed them.","B wild cereals were more nutritious than farmed ones.","C farming began in the Middle East.","D cereals were first planted twenty thousand years ago."],"correct":0,"evidence":"People were collecting the seeds of wild cereals long before anyone farmed them","why":{"en":"\"People were collecting the seeds of wild cereals long before anyone farmed them.\" Planting is not dated to that time (D).","tr":"\"İnsanlar yabani tahılların tohumlarını, kimse onları ekmeden çok önce topluyordu.\" Ekim o döneme tarihlenmiyor (D).","fa":"«مردم خیلی پیش از آنکه کسی غلات وحشی را بکارد، دانه‌هایشان را جمع می‌کردند». کاشت به آن زمان نسبت داده نشده (D)."},"trap":["TR-paraphrase","PARA-research"]},{"n":29,"kind":"mcq","prompt":"What is important about the stone pillars in south-eastern Turkey?","options":["A They were built by the first farmers.","B They are the oldest buildings in the world.","C They show that people farmed before they built monuments.","D They show that large-scale building came before farming there."],"correct":3,"evidence":"Large-scale building, in other words, came before farming in this region","why":{"en":"The builders were hunter-gatherers: \"Large-scale building... came before farming in this region, not after it.\" C reverses the order.","tr":"İnşa edenler avcı-toplayıcılardı: \"Büyük ölçekli yapılaşma... bu bölgede tarımdan önce geldi, sonra değil.\" C sırayı tersine çeviriyor.","fa":"سازندگانش شکارچی-گردآورنده بودند: «ساخت‌وساز بزرگ... در این منطقه قبل از کشاورزی آمد، نه بعد از آن». C ترتیب را برعکس می‌کند."},"trap":["TR-paraphrase","PARA-cause"]},{"n":30,"kind":"mcq","prompt":"What do skeletons of early farmers often show?","options":["A They lived longer than hunter-gatherers.","B They were less healthy than the hunter-gatherers before them.","C They ate a more varied diet.","D They suffered from fewer infections."],"correct":1,"evidence":"early farmers were shorter, had worse teeth and suffered more from disease","why":{"en":"\"Shorter, had worse teeth and suffered more from disease\": less healthy. Their diet was less varied and infections spread more.","tr":"\"Daha kısa, dişleri daha kötü ve daha çok hastalık çekiyorlardı\": daha az sağlıklı. Beslenmeleri daha az çeşitliydi, enfeksiyonlar daha çok yayılıyordu.","fa":"«کوتاه‌تر بودند، دندان‌های بدتری داشتند و بیشتر بیمار می‌شدند»: کمتر سالم. رژیمشان کمتر متنوع بود و عفونت بیشتر پخش می‌شد."},"trap":["TR-paraphrase"]}]},{"instruction":"Questions 31-34. Complete each sentence with the correct ending, A-F, below. Write the correct letter, A-F, in boxes 31-34 on your answer sheet.","qtype":"sentence-endings","bank":["A in several regions that were not in contact with each other.","B because its seeds stay attached until harvest.","C repeatedly between growing crops and gathering wild food over a long period.","D because farming could support larger numbers from the same amount of land.","E because hunting had become impossible.","F only after the first cities had been built."],"questions":[{"n":31,"kind":"match","prompt":"Plants were domesticated","correct":0,"evidence":"Plants were domesticated independently in at least half a dozen regions","why":{"en":"\"Independently in at least half a dozen regions\": several regions with no contact (A).","tr":"\"En az yarım düzine bölgede birbirinden bağımsız olarak\": birbiriyle teması olmayan birkaç bölge (A).","fa":"«به‌طور مستقل در دست‌کم شش منطقه»: چند منطقه بدون ارتباط با هم (A)."},"trap":["TR-paraphrase"]},{"n":32,"kind":"match","prompt":"In some places, people seem to have switched","correct":2,"evidence":"groups seem to have moved back and forth between farming and foraging for many generations","why":{"en":"\"Moved back and forth between farming and foraging for many generations\" (C).","tr":"\"Pek çok kuşak boyunca tarım ile toplayıcılık arasında gidip geldiler\" (C).","fa":"«نسل‌ها بین کشاورزی و جمع‌آوری غذای وحشی رفت‌وآمد داشتند» (C)."},"trap":["TR-paraphrase"]},{"n":33,"kind":"match","prompt":"Domesticated wheat is easier to harvest than wild wheat","correct":1,"evidence":"Domesticated wheat keeps its seeds on the stalk until someone cuts it","why":{"en":"It \"keeps its seeds on the stalk until someone cuts it\" (B). Wild wheat drops them when ripe.","tr":"\"Tohumlarını biri kesene kadar sapında tutar\" (B). Yabani buğday olgunlaşınca döker.","fa":"«دانه‌هایش را تا کسی آن را درو کند روی ساقه نگه می‌دارد» (B). گندم وحشی وقتی رسید آن‌ها را می‌ریزد."},"trap":["TR-paraphrase","PARA-cause"]},{"n":34,"kind":"match","prompt":"Farming populations grew until they replaced their neighbours","correct":3,"evidence":"it allowed far more people to live on the same area of land","why":{"en":"\"It allowed far more people to live on the same area of land\" (D). Hunting becoming impossible (E) is never said.","tr":"\"Aynı alanda çok daha fazla insanın yaşamasına imkân verdi\" (D). Avlanmanın imkânsızlaştığı (E) hiç söylenmiyor.","fa":"«باعث شد آدم‌های خیلی بیشتری روی همان مقدار زمین زندگی کنند» (D). اینکه شکار غیرممکن شده بود (E) هیچ‌جا گفته نشده."},"trap":["TR-paraphrase","PARA-cause"]}]},{"instruction":"Questions 35-40. Do the following statements agree with the views of the writer in Reading Passage 3? In boxes 35-40 on your answer sheet, write YES if the statement agrees with the views of the writer, NO if the statement contradicts the views of the writer, NOT GIVEN if it is impossible to say what the writer thinks about this.","qtype":"ynng","questions":[{"n":35,"kind":"ynng","prompt":"The phrase \"Neolithic Revolution\" has given people a misleading picture of the past.","correct":"YES","evidence":"I believe it has also done a good deal of harm","why":{"en":"The writer believes the phrase \"has also done a good deal of harm\", because the story it tells \"now looks doubtful\".","tr":"Yazar ifadenin \"epey zarar da verdiğine\" inanıyor, çünkü anlattığı hikâye \"artık şüpheli görünüyor\".","fa":"نویسنده باور دارد این عبارت «آسیب زیادی هم زده»، چون داستانی که می‌گوید «حالا مشکوک به نظر می‌رسد»."},"trap":["TR-whosevoice","TR-paraphrase"]},{"n":36,"kind":"ynng","prompt":"Climate change on its own explains why some groups began to farm.","correct":"NO","evidence":"although climate alone cannot explain why particular groups chose to farm","why":{"en":"Climate \"made this experimentation possible\", but \"climate alone cannot explain\" the choice.","tr":"İklim \"bu denemeleri mümkün kıldı\" ama seçimi \"tek başına açıklayamaz\".","fa":"آب‌وهوا «این آزمون‌وخطا را ممکن کرد»، اما «به‌تنهایی نمی‌تواند» انتخاب را توضیح بدهد."},"trap":["TR-whosevoice","PARA-cause"]},{"n":37,"kind":"ynng","prompt":"Early farmers were less healthy than hunter-gatherers in every region.","correct":"NO","evidence":"This pattern is found in many regions, though not in all","why":{"en":"\"In many regions, though not in all\": \"every region\" goes against the writer.","tr":"\"Birçok bölgede, ama hepsinde değil\": \"her bölge\" yazara ters düşüyor.","fa":"«در خیلی از منطقه‌ها، اما نه همه»: «هر منطقه» خلاف نظر نویسنده است."},"trap":["TR-NGvsF"]},{"n":38,"kind":"ynng","prompt":"Agriculture was the worst mistake in human history.","correct":"NO","evidence":"I cannot agree with the popular writer","why":{"en":"That is another writer’s phrase. The writer says \"I cannot agree\": nobody could foresee the result.","tr":"Bu başka bir yazarın ifadesi. Yazar \"katılamam\" diyor: kimse sonucu önceden göremezdi.","fa":"این عبارتِ نویسنده‌ی دیگری است. نویسنده می‌گوید «نمی‌توانم موافق باشم»: هیچ‌کس نتیجه را از قبل نمی‌دید."},"trap":["TR-whosevoice"]},{"n":39,"kind":"ynng","prompt":"More money should be spent on excavating ancient sites in Africa.","correct":"NOT GIVEN","evidence":"only a small part of the site has so far been uncovered","why":{"en":"The writer says only part of the Turkish site has been dug, but gives no view on spending or on Africa.","tr":"Yazar Türkiye’deki alanın yalnızca bir kısmının kazıldığını söylüyor ama harcama ya da Afrika hakkında görüş bildirmiyor.","fa":"نویسنده می‌گوید فقط بخشی از محوطه‌ی ترکیه کاوش شده، اما درباره‌ی هزینه یا آفریقا نظری نمی‌دهد."},"trap":["TR-NGvsF"]},{"n":40,"kind":"ynng","prompt":"School textbooks give an out-of-date account of how farming began.","correct":"YES","evidence":"None of this has yet reached most school textbooks","why":{"en":"Textbooks \"still tell children about a single revolution in a single place\", and the writer calls this \"a pity\".","tr":"Ders kitapları \"çocuklara hâlâ tek bir yerde tek bir devrimi anlatıyor\" ve yazar buna \"yazık\" diyor.","fa":"کتاب‌های درسی «هنوز برای بچه‌ها از یک انقلاب در یک جا می‌گویند» و نویسنده این را «حیف» می‌داند."},"trap":["TR-paraphrase"]}]}],"id":"c-x03-r3-d","course":"ielts-exams","exam":"exam-03","unit":"x03-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Nobody could have foreseen the result.\" Foreseen means...","options":["known in advance","paid for","wanted"],"correct":0,"why":{"en":"To foresee = to know before it happens.","tr":"Foresee = olmadan önce bilmek.","fa":"foresee یعنی قبل از اتفاق افتادن دانستن."}},{"tests":"paraphrase","point":1,"prompt":"Which word means \"separately, without contact with each other\"?","options":["gradually","deliberately","independently"],"correct":2,"why":{"en":"Independently = on their own, not influenced by others.","tr":"Independently = kendi başına, başkalarından etkilenmeden.","fa":"independently یعنی جداگانه، بدون تأثیر از دیگران."}},{"tests":"method","point":2,"prompt":"Two endings both make a grammatical sentence. How do you choose?","options":["Choose the longer ending","Check what the passage says about that beginning","Choose the one that repeats words from the passage"],"correct":1,"why":{"en":"Grammar is not enough: the ending must match the meaning of the passage.","tr":"Dilbilgisi yetmez: son, metnin anlamıyla örtüşmeli.","fa":"دستور زبان کافی نیست: پایان باید با معنی متن جور باشد."}},{"tests":"trap","point":3,"prompt":"Text: \"One historian called the war pointless. I find that view far too simple.\" Statement: \"The war was pointless.\" YES, NO or NOT GIVEN?","options":["NO","YES","NOT GIVEN"],"correct":0,"why":{"en":"\"Pointless\" is the historian’s word. The writer rejects it as \"far too simple\".","tr":"\"Anlamsız\" tarihçinin kelimesi. Yazar bunu \"fazla basit\" bularak reddediyor.","fa":"«بی‌فایده» کلمه‌ی آن تاریخ‌دان است. نویسنده آن را «خیلی ساده‌انگارانه» می‌داند و ردش می‌کند."}},{"tests":"trap","point":3,"prompt":"An ending says \"...in all parts of the world\". The passage says \"in many regions, though not in all\". Is the ending correct?","options":["Yes: the regions are mentioned","Only partly","No: \"all\" goes beyond the passage"],"correct":2,"why":{"en":"\"Not in all\" contradicts \"in all parts of the world\".","tr":"\"Hepsinde değil\", \"dünyanın her yerinde\" ile çelişiyor.","fa":"«نه در همه» با «در همه‌ی جهان» تناقض دارد."}}],"id":"c-x03-r3-x","course":"ielts-exams","exam":"exam-03","unit":"x03-r3"},"gt":{"explain":{"title":{"en":"GT Reading Section 3: a local history","tr":"GT Reading Section 3: bir yerel tarih","fa":"GT Reading Section 3: یک تاریخچه‌ی محلی"},"objective":{"en":"In this lesson you will learn to choose a heading for each section of a long history article, answer multiple-choice questions about causes and decisions, and complete a summary with single words from the text.","tr":"Bu derste uzun bir tarih makalesinin her bölümü için bir başlık seçmeyi, nedenler ve kararlarla ilgili çoktan seçmeli soruları cevaplamayı ve bir özeti metindeki tek kelimelerle tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری برای هر بخش یک مقاله‌ی تاریخی بلند عنوان انتخاب کنی، به سؤال‌های چندگزینه‌ای درباره‌ی علت‌ها و تصمیم‌ها جواب بدهی و یک خلاصه را با تک‌کلمه‌هایی از متن کامل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Sections","tr":"Bölüm","fa":"بخش"},"value":"A-F"},{"label":{"en":"Headings","tr":"Başlıklar","fa":"عنوان‌ها"},"value":"i-ix"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a headland that became a reserve","tr":"Bu sınav: koruma alanına dönüşen bir burun","fa":"این آزمون: دماغه‌ای که منطقه‌ی حفاظت‌شده شد"},"intro":{"en":"Section 3 is one long article for a general reader. Local and natural history is a frequent subject: the article moves through time, so each section usually covers one period or one turning point.","tr":"Section 3 genel okur için uzun bir makaledir. Yerel tarih ve doğa tarihi sık çıkan bir konudur: makale zaman içinde ilerler, bu yüzden her bölüm genelde bir dönemi ya da bir dönüm noktasını anlatır.","fa":"Section 3 یک مقاله‌ی بلند برای خواننده‌ی عمومی است. تاریخ محلی و تاریخ طبیعی موضوع پرتکراری است: مقاله در زمان جلو می‌رود، پس هر بخش معمولاً یک دوره یا یک نقطه‌ی عطف را می‌گوید."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x03-r3gt-ctx","exam":true,"patterns":["GT3-history","PARA-cause"],"often":{"pattern":"GT3-history","n":14,"of":40,"label":{"en":"Comes up often in the real exam: 14 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 14’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۴ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"The history of a nature reserve","tr":"Bir doğa koruma alanının tarihi","fa":"تاریخچه‌ی یک منطقه‌ی حفاظت‌شده"},"asks":{"en":"Section 3 is one long article. Here it tells the history of a coastal headland in six stages: work, war, a fight against building, a public appeal, careful management and a new plan for the sea.","tr":"Section 3 tek bir uzun makaledir. Burada bir kıyı burnunun tarihini altı aşamada anlatıyor: çalışma, savaş, yapılaşmaya karşı mücadele, halka açık bir bağış kampanyası, dikkatli yönetim ve deniz için yeni bir plan.","fa":"Section 3 یک مقاله‌ی بلند است. این‌جا تاریخچه‌ی یک دماغه‌ی ساحلی را در شش مرحله می‌گوید: کار، جنگ، مبارزه با ساخت‌وساز، یک کارزار جمع‌آوری کمک مردمی، مدیریت دقیق و برنامه‌ای تازه برای دریا."},"fields":["Before the war","The war years","After the war","Buying the land","Managing the reserve","Today"],"words":[{"a":"headland","b":"land that sticks out into the sea","tr":"burun (kara çıkıntısı)","fa":"دماغه"},{"a":"graze","b":"eat grass in a field","tr":"otlamak","fa":"چریدن"},{"a":"firing range","b":"a place for practising shooting","tr":"atış alanı","fa":"میدان تیر"},{"a":"fell into ruin","b":"were left to fall apart","tr":"harabeye döndü","fa":"ویران شد"},{"a":"turned down","b":"refused / rejected","tr":"reddedildi","fa":"رد شد"},{"a":"appeal","b":"a request for money from the public","tr":"bağış çağrısı","fa":"فراخوان کمک مالی"},{"a":"donations","b":"money given freely","tr":"bağışlar","fa":"کمک‌های مالی"},{"a":"deliberately","b":"on purpose","tr":"bilerek","fa":"عمداً"},{"a":"compensation","b":"money paid for a loss","tr":"tazminat","fa":"غرامت"},{"a":"absorb","b":"take in / soak up","tr":"emmek","fa":"جذب کردن"}],"traps":[{"en":"A heading can share a word with a section (\"visitor centre\", \"fishing\") but describe only one detail. Choose the heading that covers the whole section.","tr":"Bir başlık bir bölümle aynı kelimeyi (\"visitor centre\", \"fishing\") paylaşıp yalnızca bir ayrıntıyı anlatabilir. Bütün bölümü kapsayan başlığı seç.","fa":"ممکن است عنوانی کلمه‌ای مشترک با یک بخش داشته باشد («visitor centre»، «fishing») اما فقط یک جزئیات را بگوید. عنوانی را انتخاب کن که کل بخش را پوشش می‌دهد."},{"en":"A summary of one section often uses other words. Find the section first, then the exact word, in the same form.","tr":"Bir bölümün özeti çoğu zaman başka kelimeler kullanır. Önce bölümü, sonra kelimenin kendisini aynı biçimde bul.","fa":"خلاصه‌ی یک بخش اغلب کلمه‌های دیگری به کار می‌برد. اول بخش را پیدا کن و بعد همان کلمه را با همان شکل."}],"example":{"text":"\"C  In 1870 a railway reached the town. Within twenty years the fishing village had become a busy holiday resort, with three hotels and a pier.\"","item":"Best heading for C: i A new hotel  ii How a railway changed a village  iii The history of fishing","answer":"ii","why":{"en":"Hotels and fishing are details; the section is about the change the railway brought.","tr":"Oteller ve balıkçılık ayrıntı; bölüm demiryolunun getirdiği değişimle ilgili.","fa":"هتل و ماهیگیری جزئیات‌اند؛ بخش درباره‌ی تغییری است که راه‌آهن آورد."}}},{"id":"GT3-history","ctx":["GT3-history"],"title":{"en":"History and heritage","tr":"Tarih ve kültürel miras","fa":"تاریخ و میراث"},"asks":{"en":"A longer text about a historical topic: a road, a bridge, a trade, a craft, an invention or a job that has disappeared. Headings follow the story; summaries and multiple choice test causes and changes.","tr":"Tarihî bir konu hakkında daha uzun bir metin: bir yol, bir köprü, bir ticaret, bir zanaat, bir icat ya da ortadan kalkmış bir meslek. Başlıklar hikâyeyi izler; özetler ve çoktan seçmeli sorular nedenleri ve değişimleri sınar.","fa":"متنی بلندتر درباره‌ی یک موضوع تاریخی: یک جاده، یک پل، یک تجارت، یک صنعت دستی، یک اختراع یا شغلی که از بین رفته. عنوان‌ها داستان را دنبال می‌کنند؛ خلاصه‌ها و سؤال‌های چندگزینه‌ای علت‌ها و تغییرها را می‌سنجند."},"fields":["The arrival of the railway","A dangerous job","Why the trade came to an end","How the material was collected","Life for the workers’ families"],"words":[{"a":"era","b":"period / age","tr":"dönem","fa":"دوره"},{"a":"originally","b":"at first / in the beginning","tr":"başlangıçta","fa":"در اصل"},{"a":"workers","b":"labourers / crew","tr":"işçiler","fa":"کارگران"},{"a":"dangerous","b":"risky / hazardous","tr":"tehlikeli","fa":"خطرناک"},{"a":"decline","b":"fall-off / became less common","tr":"gerileme","fa":"افول"},{"a":"take over from","b":"replace","tr":"... -in yerini almak","fa":"جای ... را گرفتن"},{"a":"skills","b":"expertise / know-how","tr":"beceriler","fa":"مهارت‌ها"},{"a":"preserved","b":"kept / still exists","tr":"korunmuş","fa":"حفظ‌شده"},{"a":"remote","b":"far from towns / isolated","tr":"ıssız, uzak","fa":"دورافتاده"},{"a":"demand","b":"what people wanted to buy","tr":"talep","fa":"تقاضا"},{"a":"eventually","b":"in the end / finally","tr":"sonunda","fa":"سرانجام"},{"a":"transport","b":"carry goods / move","tr":"taşımak","fa":"حمل کردن"}],"traps":[{"en":"Headings in time order: two paragraphs may describe the same period from different angles.","tr":"Kronolojik başlıklar: iki paragraf aynı dönemi farklı açılardan anlatabilir.","fa":"عنوان‌های زمانی: دو پاراگراف ممکن است یک دوره را از دو زاویه توصیف کنند."},{"en":"Summary gaps: the word must also fit the grammar of the summary sentence.","tr":"Özet boşlukları: kelime özet cümlesinin dilbilgisine de uymalı.","fa":"جاهای خالی خلاصه: کلمه باید با دستور جمله‌ی خلاصه هم جور باشد."}],"example":{"text":"C  By the 1950s, lorries could carry goods faster and more cheaply than boats. Traffic on the canal fell year by year, and the last regular cargo boat stopped running in 1963.","item":"Choose the heading for paragraph C:  i  Losing out to road transport   ii  How the canal was dug   iii  A dangerous journey","answer":"i","why":{"en":"Lorries were faster and cheaper, so canal traffic fell: losing out to road transport.","tr":"Kamyonlar daha hızlı ve ucuzdu; kanal trafiği azaldı: karayoluna yenilmek.","fa":"کامیون‌ها سریع‌تر و ارزان‌تر بودند، پس رفت‌وآمد کانال کم شد: باختن به حمل‌ونقل جاده‌ای."}},"track":"gt","general":true,"patterns":["GT3-history"],"often":{"pattern":"GT3-history","n":14,"of":40,"label":{"en":"Comes up often in the real exam: 14 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 14’ünde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۴ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Headings, questions, a summary","tr":"Başlıklar, sorular, bir özet","fa":"عنوان‌ها، سؤال‌ها، یک خلاصه"},"body":{"en":"Questions 28-33: choose a heading, i-ix, for each of six sections; three headings are extra. Questions 34-36: multiple choice, A-D. Questions 37-40: complete a summary of one part of the article with ONE WORD ONLY.","tr":"Soru 28-33: altı bölümün her biri için i-ix arasından bir başlık seç; üç başlık fazladır. Soru 34-36: çoktan seçmeli, A-D. Soru 37-40: makalenin bir bölümünün özetini ONE WORD ONLY ile tamamla.","fa":"سؤال‌های ۲۸ تا ۳۳: برای هر کدام از شش بخش یک عنوان از i تا ix انتخاب کن؛ سه عنوان اضافه‌اند. سؤال‌های ۳۴ تا ۳۶: چندگزینه‌ای، A تا D. سؤال‌های ۳۷ تا ۴۰: خلاصه‌ی یک بخش مقاله را با ONE WORD ONLY کامل کن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One period, one heading","tr":"Bir dönem, bir başlık","fa":"یک دوره، یک عنوان"},"steps":[{"en":"Read each section and ask: what changed in this period, and why?","tr":"Her bölümü oku ve sor: bu dönemde ne değişti ve neden?","fa":"هر بخش را بخوان و بپرس: در این دوره چه چیزی عوض شد و چرا؟"},{"en":"Match that change to a heading, and cross the heading out.","tr":"Bu değişikliği bir başlıkla eşleştir ve başlığın üstünü çiz.","fa":"آن تغییر را به یک عنوان وصل کن و عنوان را خط بزن."},{"en":"For the summary, find the section it comes from first; the answers will be in that section, in order.","tr":"Özet için önce geldiği bölümü bul; cevaplar o bölümde, sırayla olacak.","fa":"برای خلاصه اول بخشی را که از آن آمده پیدا کن؛ جواب‌ها در همان بخش و به ترتیب‌اند."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"A detail is not a heading","tr":"Ayrıntı başlık değildir","fa":"جزئیات عنوان نیست"},"body":{"en":"Extra headings are often built from one detail in a section: a building, a job, a date. They look right because they share a word, but they do not cover the whole section.","tr":"Fazladan başlıklar çoğu zaman bir bölümdeki tek bir ayrıntıdan kurulur: bir bina, bir iş, bir tarih. Bir kelimeyi paylaştıkları için doğru görünürler ama bütün bölümü kapsamazlar.","fa":"عنوان‌های اضافه اغلب از یک جزئیات در یک بخش ساخته می‌شوند: یک ساختمان، یک شغل، یک تاریخ. چون کلمه‌ای مشترک دارند درست به نظر می‌رسند، اما کل بخش را پوشش نمی‌دهند."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One summary gap, step by step","tr":"Bir özet boşluğu, adım adım","fa":"یک جای خالی خلاصه، قدم به قدم"},"instruction":"Complete the summary. Choose ONE WORD ONLY from the text.","text":"\"After the flood of 1953, the council planted thousands of trees on the hills above the river, and the town has not flooded since.\"","item":"Since the 1950s, the town has been protected by ___ planted on the hills.","answer":"trees","walk":[{"en":"Find the section: the one about the flood.","tr":"Bölümü bul: selle ilgili olanı.","fa":"بخش را پیدا کن: همانی که درباره‌ی سیل است."},{"en":"\"Protected by\" matches \"has not flooded since\"; \"planted\" is printed.","tr":"\"Protected by\", \"o zamandan beri sel olmadı\" ile eşleşiyor; \"planted\" yazılı.","fa":"«protected by» با «از آن موقع سیل نیامده» جور است؛ «planted» چاپ شده."},{"en":"Copy one word, plural as in the text: trees.","tr":"Tek kelime kopyala, metindeki gibi çoğul: trees.","fa":"یک کلمه کپی کن، جمع مثل متن: trees."}]},"quick":{"prompt":"A section describes a factory closing, workers leaving the town and shops shutting. Which heading fits it best?","options":["The history of the factory","Why shops are important","A town in decline"],"correct":2,"why":{"en":"All three details show the town getting smaller and poorer; the other headings cover only one detail.","tr":"Üç ayrıntının hepsi kasabanın küçüldüğünü ve yoksullaştığını gösteriyor; diğer başlıklar yalnızca bir ayrıntıyı kapsıyor.","fa":"هر سه جزئیات نشان می‌دهند شهر کوچک‌تر و فقیرتر می‌شود؛ عنوان‌های دیگر فقط یک جزئیات را پوشش می‌دهند."}},"remember":{"en":"A heading names what changed in the whole section; a summary lives in one section, in order.","tr":"Başlık bütün bölümde neyin değiştiğini söyler; özet tek bir bölümün içinde, sırayla yer alır.","fa":"عنوان می‌گوید در کل بخش چه چیزی عوض شد؛ خلاصه در یک بخش و به ترتیب است."},"type":"explain","id":"c-x03-r3-e-gt","course":"ielts-exams","exam":"exam-03","unit":"x03-r3"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 3","title":{"en":"From marsh to sanctuary","tr":"Bataklıktan sığınağa","fa":"از مرداب تا پناهگاه"},"timed":20,"ctx":["GT3-history"],"texts":[{"title":"From marsh to sanctuary: the story of Brancombe Point","kind":"article","body":"A  For hundreds of years, the flat, muddy land at Brancombe Point was a place of work rather than a place to visit. Fishermen kept their boats in the creeks, and families boiled sea water in large iron pans to make salt, which they sold in the market towns inland. Behind the sea wall, sheep grazed on the marshes for most of the year, and their wool was an important source of income for the village. Nobody thought of the area as beautiful; it was simply useful. Some of the old salt pans can still be seen today as shallow, square ponds near the creek.\n\nB  The Second World War changed everything. In 1940 the army took over the whole headland and turned it into a firing range for training soldiers. Fences went up, warning signs were posted along the paths and the public was kept out entirely. The fishermen moved their boats to another harbour and the salt pans fell into ruin. Yet the war had an effect that nobody had planned. With no people, dogs or farm animals on the marshes, ground-nesting birds such as terns and avocets returned in large numbers, and by the time the army left in 1952, the headland had some of the richest birdlife on the coast. Several of the concrete buildings used by the soldiers still stand, and they are now used as hides by birdwatchers.\n\nC  Peace brought new threats. A developer soon announced plans to build a holiday camp with five hundred chalets on the headland, and a second company wanted a large caravan park beside the beach. Many local people welcomed the idea of new jobs, but others were alarmed. A retired schoolteacher, Agnes Holloway, who had been recording the birds for years, organised public meetings and wrote to every newspaper in the region. Her detailed notebooks, which listed every species she had seen on the headland, were later used as evidence. After a long public inquiry, both plans were turned down in 1959.\n\nD  Turning the headland down for development did not, however, protect it for ever. The land was still for sale, and another plan might follow. In 1961 a national wildlife charity launched an appeal to buy Brancombe Point, and over the following year thousands of people sent donations, many of them only a few shillings. A local newspaper printed the name of every person who gave money, and the list filled several pages. The money was raised in time, and in 1962 the headland became one of the first nature reserves on that part of the coast to be owned by a charity.\n\nE  At first the managers of the new reserve believed that the best policy was to leave nature alone. Within ten years, however, the open grassland where many birds nested had become covered in rough grass and bushes, and the numbers of some species began to fall. The answer, surprisingly, was to bring back the sheep. Grazing keeps the grass short, which is exactly what ground-nesting birds need, and today a local farmer's flock spends each autumn and winter on the marshes. Wooden boardwalks were also built so that visitors could see the birds without disturbing them, and a small visitor centre opened in 1985. Volunteers also cut back bushes by hand every winter, and school groups visit throughout the year to learn about the marshes and the birds that depend on them.\n\nF  The greatest challenge facing the reserve now is the sea itself. As sea levels rise, the old sea wall has become more and more expensive to repair, and in storms the water has come close to breaking through. In 2015, after years of study, the managers made a bold decision: instead of strengthening the wall, they deliberately opened a gap in it and allowed the sea to flood the low fields behind. Not everyone agreed with the decision, and the farmers who lost fields that their families had worked for generations were paid compensation. The result has been a new area of saltmarsh, which absorbs the energy of the waves and so helps to protect the coast from storms. It also provides rich feeding grounds for wading birds, whose numbers have more than doubled since the wall was opened. The project has been visited by planners from all over the country, many of whom face the same choice between holding back the sea and making room for it. The managers themselves believe that, in the long run, the sea will decide the shape of the headland whatever people do."}],"groups":[{"text":0,"instruction":"Questions 28-33. The text has six sections, A-F. Choose the correct heading for each section from the list of headings below. Write the correct number, i-ix, in boxes 28-33 on your answer sheet.","qtype":"headings","bank":["i An unexpected benefit of keeping people out","ii How the visitor centre was designed","iii Letting the sea back in","iv Centuries of work on the marshes","v A fight against new building","vi The decline of the fishing industry","vii Animals as part of the management plan","viii Raising money to buy the land","ix Why the birds left the area"],"questions":[{"n":28,"kind":"match","prompt":"Section A","correct":3,"evidence":"it was simply useful","why":{"en":"Fishing, salt-making and sheep: centuries of work (iv). Fishing is one detail, so vi is wrong.","tr":"Balıkçılık, tuz yapımı ve koyunlar: yüzyıllarca süren çalışma (iv). Balıkçılık bir ayrıntı; vi yanlış.","fa":"ماهیگیری، نمک‌سازی و گوسفند: قرن‌ها کار (iv). ماهیگیری یک جزئیات است، پس vi غلط است."},"trap":["TR-samewords","TR-detail"]},{"n":29,"kind":"match","prompt":"Section B","correct":0,"evidence":"the war had an effect that nobody had planned","why":{"en":"The army kept people out, and birds returned: an unexpected benefit (i).","tr":"Ordu insanları uzak tuttu ve kuşlar geri döndü: beklenmedik bir fayda (i).","fa":"ارتش مردم را دور نگه داشت و پرنده‌ها برگشتند: یک فایده‌ی غیرمنتظره (i)."},"trap":["TR-paraphrase","PARA-cause"]},{"n":30,"kind":"match","prompt":"Section C","correct":4,"evidence":"both plans were turned down in 1959","why":{"en":"Plans for a holiday camp and a caravan park were opposed and turned down: a fight against new building (v).","tr":"Tatil köyü ve karavan parkı planlarına karşı çıkıldı ve reddedildi: yeni yapılaşmaya karşı mücadele (v).","fa":"با طرح‌های اردوگاه تعطیلات و پارک کاروان مخالفت و ردشان کردند: مبارزه با ساخت‌وساز تازه (v)."},"trap":["TR-paraphrase"]},{"n":31,"kind":"match","prompt":"Section D","correct":7,"evidence":"launched an appeal to buy Brancombe Point","why":{"en":"A charity raised money from the public to buy the headland (viii).","tr":"Bir hayır kurumu burnu satın almak için halktan para topladı (viii).","fa":"یک خیریه برای خریدن دماغه از مردم پول جمع کرد (viii)."},"trap":["TR-paraphrase"]},{"n":32,"kind":"match","prompt":"Section E","correct":6,"evidence":"The answer, surprisingly, was to bring back the sheep","why":{"en":"Sheep keep the grass short for nesting birds: animals in the management plan (vii). The visitor centre is one detail (ii).","tr":"Koyunlar yuva yapan kuşlar için otu kısa tutuyor: yönetim planının parçası olan hayvanlar (vii). Ziyaretçi merkezi bir ayrıntı (ii).","fa":"گوسفندها علف را برای پرنده‌های لانه‌ساز کوتاه نگه می‌دارند: حیوان‌ها به‌عنوان بخشی از برنامه‌ی مدیریت (vii). مرکز بازدیدکنندگان یک جزئیات است (ii)."},"trap":["TR-samewords","TR-detail"]},{"n":33,"kind":"match","prompt":"Section F","correct":2,"evidence":"allowed the sea to flood the low fields behind","why":{"en":"The managers opened the sea wall on purpose: letting the sea back in (iii).","tr":"Yöneticiler deniz duvarını bilerek açtı: denizi yeniden içeri almak (iii).","fa":"مدیران دیوار دریایی را عمداً باز کردند: راه دادن دوباره‌ی دریا (iii)."},"trap":["TR-paraphrase"]}]},{"text":0,"instruction":"Questions 34-36. Choose the correct letter, A, B, C or D. Write the correct letter in boxes 34-36 on your answer sheet.","qtype":"mcq","questions":[{"n":34,"kind":"mcq","prompt":"Why did birds return to the headland in the 1940s?","options":["A The army fed them.","B People and animals were kept off the land.","C The salt pans filled with water.","D The fishermen stopped fishing."],"correct":1,"evidence":"With no people, dogs or farm animals on the marshes","why":{"en":"\"With no people, dogs or farm animals on the marshes, ground-nesting birds... returned.\"","tr":"\"Bataklıklarda insan, köpek ya da çiftlik hayvanı olmayınca yerde yuva yapan kuşlar... geri döndü.\"","fa":"«وقتی هیچ آدم، سگ یا حیوان مزرعه‌ای روی مرداب‌ها نبود، پرنده‌های لانه‌ساز روی زمین... برگشتند»."},"trap":["TR-detail","PARA-cause"]},{"n":35,"kind":"mcq","prompt":"What happened to the plans for a holiday camp?","options":["A They were rejected after a public inquiry.","B The developer changed its mind.","C They became plans for a caravan park.","D They were approved but never carried out."],"correct":0,"evidence":"both plans were turned down in 1959","why":{"en":"\"After a long public inquiry, both plans were turned down in 1959\": rejected.","tr":"\"Uzun bir kamu soruşturmasından sonra iki plan da 1959’da reddedildi.\"","fa":"«بعد از یک بررسی عمومی طولانی، هر دو طرح در ۱۹۵۹ رد شدند»."},"trap":["TR-paraphrase"]},{"n":36,"kind":"mcq","prompt":"Why were sheep brought back to the reserve?","options":["A to earn money from their wool","B to keep visitors off the marshes","C to please the local farmers","D to keep the grass short for nesting birds"],"correct":3,"evidence":"Grazing keeps the grass short, which is exactly what ground-nesting birds need","why":{"en":"\"Grazing keeps the grass short, which is exactly what ground-nesting birds need.\" Wool was important long before, in section A.","tr":"\"Otlatma otu kısa tutar; yerde yuva yapan kuşların tam da ihtiyacı budur.\" Yün çok önceleri, A bölümünde önemliydi.","fa":"«چرا کردن علف را کوتاه نگه می‌دارد، همان چیزی که پرنده‌های لانه‌ساز روی زمین لازم دارند». پشم خیلی قبل‌تر، در بخش A، مهم بود."},"trap":["TR-detail","TR-samewords"]}]},{"text":0,"instruction":"Questions 37-40. Complete the summary below. Choose ONE WORD ONLY from the text for each answer. Write your answers in boxes 37-40 on your answer sheet.","qtype":"summary","summaryTitle":"Making room for the sea","questions":[{"n":37,"kind":"gap","prompt":"Instead of making the old sea ___ stronger, the managers opened a gap in it.","accept":["wall"],"limit":1,"evidence":"instead of strengthening the wall","why":{"en":"\"Instead of strengthening the wall, they deliberately opened a gap in it.\"","tr":"\"Duvarı güçlendirmek yerine onda bilerek bir açıklık yaptılar.\"","fa":"«به جای محکم‌تر کردن دیوار، عمداً در آن شکافی باز کردند»."},"trap":["TR-paraphrase","TR-limit"]},{"n":38,"kind":"gap","prompt":"Farmers who lost fields were given ___.","accept":["compensation"],"limit":1,"evidence":"were paid compensation","why":{"en":"The farmers \"were paid compensation\": given = paid.","tr":"Çiftçilere \"tazminat ödendi\": given = paid.","fa":"به کشاورزها «غرامت پرداخت شد»: given یعنی paid."},"trap":["TR-paraphrase"]},{"n":39,"kind":"gap","prompt":"The flooded fields have become a new area of ___.","accept":["saltmarsh"],"limit":1,"evidence":"The result has been a new area of saltmarsh","why":{"en":"\"The result has been a new area of saltmarsh.\" One word.","tr":"\"Sonuç yeni bir tuzlu bataklık alanı oldu.\" Tek kelime.","fa":"«نتیجه، منطقه‌ای تازه از مرداب شور بوده». یک کلمه."},"trap":["TR-limit"]},{"n":40,"kind":"gap","prompt":"This helps to protect the coast from ___ and gives wading birds more food.","accept":["storms"],"limit":1,"evidence":"helps to protect the coast from storms","why":{"en":"\"It absorbs the energy of the waves and so helps to protect the coast from storms.\" Plural.","tr":"\"Dalgaların enerjisini emer ve böylece kıyıyı fırtınalardan korumaya yardım eder.\" Çoğul.","fa":"«انرژی موج‌ها را جذب می‌کند و این‌طور به محافظت از ساحل در برابر طوفان‌ها کمک می‌کند». جمع."},"trap":["TR-plural","PARA-cause"]}]}],"id":"c-x03-r3-d-gt","course":"ielts-exams","exam":"exam-03","unit":"x03-r3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The plans were turned down.\" This means they were...","options":["accepted","rejected","delayed"],"correct":1,"why":{"en":"Turned down = refused.","tr":"Turned down = reddedildi.","fa":"turned down یعنی رد شد."}},{"tests":"paraphrase","point":2,"prompt":"A heading says \"Raising money from the public\". Which phrase in a section would match it?","options":["an appeal for donations","a fall in prices","a new tax on visitors"],"correct":0,"why":{"en":"An appeal for donations asks the public to give money.","tr":"Bağış çağrısı halktan para vermesini ister.","fa":"فراخوان کمک مالی از مردم می‌خواهد پول بدهند."}},{"tests":"method","point":2,"prompt":"Where do you look for the answers to a summary of one part of an article?","options":["anywhere in the article","only in the last section","in the section that the summary describes, in order"],"correct":2,"why":{"en":"A summary usually covers one section, and its answers come in order.","tr":"Bir özet genelde tek bir bölümü kapsar ve cevapları sırayla gelir.","fa":"خلاصه معمولاً یک بخش را پوشش می‌دهد و جواب‌هایش به ترتیب می‌آیند."}},{"tests":"trap","point":3,"prompt":"A section is about sheep grazing, and one sentence mentions a new visitor centre. Which heading fits the section?","options":["a heading about the visitor centre","a heading about grazing animals","either heading"],"correct":1,"why":{"en":"The visitor centre is one detail; the heading must cover the main idea.","tr":"Ziyaretçi merkezi bir ayrıntı; başlık ana fikri kapsamalı.","fa":"مرکز بازدیدکنندگان یک جزئیات است؛ عنوان باید ایده‌ی اصلی را پوشش بدهد."}}],"id":"c-x03-r3-x-gt","course":"ielts-exams","exam":"exam-03","unit":"x03-r3"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
